/**
 * The machine. Every call says what time it is and answers with what to
 * do.
 */
public protocol AgentMachineProtocol: AnyObject, Sendable {
    
    /**
     * The announced record as stored, once it can be believed: it joins
     * the one this process kept, then is saved (B348).
     */
    func adoptAnnounced(announced: [String: Double], now: Double)  -> [AgentEffectValue]
    
    func bell(conn: String, pane: String, place: AgentPaneWhereValue, now: Double)  -> [AgentEffectValue]
    
    func cycleHeadline(now: Double)  -> [AgentEffectValue]
    
    /**
     * The agent cards the notification center holds, by identifier, and
     * the saved connections' ids (none while they can't be told): a card
     * nothing stands behind any more is withdrawn (B433).
     */
    func delivered(ids: [String], saved: [String]?, now: Double)  -> [AgentEffectValue]
    
    /**
     * One poll of `conn`'s stamps. `interval`: how often its stamps
     * arrive, in seconds — tmux's, the sweep that polls them; herdr's,
     * [`herdr_stamp_interval`]. A stamp holds that long and a margin
     * (`moshpit_agents::stamp_hold`, B346).
     */
    func hooks(conn: String, hooks: [AgentHookInValue], now: Double, interval: Double)  -> [AgentEffectValue]
    
    func isTracking()  -> Bool
    
    func output(conn: String, pane: String, place: AgentPaneWhereValue, now: Double)  -> [AgentEffectValue]
    
    /**
     * The switches as they are now, and what changing them does: the
     * island ended when the Live Activity is switched off (B436).
     */
    func setSettings(settings: AgentSettingsValue)  -> [AgentEffectValue]
    
    func stateSinceByPane(conn: String)  -> [String: Double]
    
    /**
     * `visible_conn`/`visible_pane`: the pane on screen (no pane: every
     * pane of that connection).
     */
    func sweep(visibleConn: String?, visiblePane: String?, now: Double)  -> [AgentEffectValue]
    
    func track(conn: String, label: String)  -> [AgentEffectValue]
    
    /**
     * The connection's tree: where each of its panes lives.
     */
    func tree(conn: String, places: [String: AgentPaneWhereValue]) 
    
    func untrack(conn: String, keepWaitingCards: Bool, now: Double)  -> [AgentEffectValue]
    
}
