// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceCredentialHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceCredentialHost = UniffiVTableCallbackInterfaceCredentialHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeCredentialHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface CredentialHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeCredentialHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface CredentialHost: handle missing in uniffiClone")
            }
        },
        credential: { (
            uniffiHandle: UInt64,
            connectionId: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> Credential in
                guard let uniffiObj = try? FfiConverterTypeCredentialHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.credential(
                     connectionId: try FfiConverterString.lift(connectionId)
                )
            }

            let uniffiHandleSuccess = { (returnValue: Credential) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeCredential_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeCredentialFailure_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        },
        sign: { (
            uniffiHandle: UInt64,
            keyRef: RustBuffer,
            data: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> PlatformSignature in
                guard let uniffiObj = try? FfiConverterTypeCredentialHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.sign(
                     keyRef: try FfiConverterString.lift(keyRef),
                     data: try FfiConverterData.lift(data)
                )
            }

            let uniffiHandleSuccess = { (returnValue: PlatformSignature) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypePlatformSignature_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeCredentialFailure_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceCredentialHost> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceCredentialHost>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitCredentialHost() {
    uniffi_moshpit_ffi_fn_init_callback_vtable_credentialhost(UniffiCallbackInterfaceCredentialHost.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCredentialHost: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<CredentialHost>()

    typealias FfiType = UInt64
    typealias SwiftType = CredentialHost

    public static func lift(_ handle: UInt64) throws -> CredentialHost {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return CredentialHostImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: CredentialHost) -> UInt64 {
         if let rustImpl = value as? CredentialHostImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CredentialHost {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CredentialHost, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCredentialHost_lift(_ handle: UInt64) throws -> CredentialHost {
    return try FfiConverterTypeCredentialHost.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCredentialHost_lower(_ value: CredentialHost) -> UInt64 {
    return FfiConverterTypeCredentialHost.lower(value)
}






/**
 * The machine, driven on the core's runtime.
 */
public protocol HostCareCoreProtocol: AnyObject, Sendable {
    
    /**
     * Wait for the care pass the delete stood down to end (at most 5 s).
     */
    func careWindDown(connection: String) async 
    
    func closeSetup(page: UInt64) 
    
    /**
     * The connection whose host has no hooks yet: the one question.
     */
    func consent()  -> CareConnection?
    
    func decline(connection: String) 
    
    /**
     * A delete of `connection` begins: care stands down for it and its
     * pairing is forgotten on this phone. False: the phone couldn't let
     * go — nothing else may be removed, and the delete is over.
     */
    func deletionBegan(connection: String)  -> Bool
    
    func deletionEnded(connection: String) 
    
    /**
     * iOS handed over a device token (hex).
     */
    func deviceToken(token: String) 
    
    func dismissConsent() 
    
    /**
     * The app came to the foreground.
     */
    func foreground() 
    
    /**
     * Forget pairings whose connection is gone, once a launch, as soon as
     * the saved connections can be told; how many were forgotten.
     */
    func forgetOrphanedPairings()  -> UInt32
    
    /**
     * Wait (at most 3 s) for a deleted connection's pairing to come off
     * its host, before its session goes (B377).
     */
    func forgetWindDown(connection: String) async 
    
    func grantConsent(connection: CareConnection) 
    
    /**
     * `connection` was saved pointing at another host or port (B328): its
     * pairing is forgotten on this phone. False: the phone couldn't let go
     * — the save must not go on.
     */
    func hostChanged(connection: String)  -> Bool
    
    /**
     * This install's id (B443), read from where no backup carries it: what
     * its pairing's conf on a host is named by. Anything but 8 to 32
     * lowercase hex digits is ignored.
     */
    func installId(id: String) 
    
    func isTending(connection: String)  -> Bool
    
    /**
     * What the person calls `connection` now: its pairing takes the name
     * (B451).
     */
    func nameConnection(connection: String, label: String) 
    
    /**
     * Open a Host Setup screen on `connection`'s host; its page id.
     */
    func openSetup(connection: CareConnection, testPane: String?)  -> UInt64
    
    /**
     * Ask iOS for a device token if anything is paired.
     */
    func registerForPush() 
    
    /**
     * iOS refused one; `why` in the person's language.
     */
    func registrationFailed(why: String) 
    
    /**
     * Why this phone has no usable relay credential, in `locale`.
     */
    func relayError(locale: String)  -> String?
    
    /**
     * The device token remembered from an earlier launch.
     */
    func restoreDeviceToken(token: String?) 
    
    /**
     * A self-test push carrying `nonce` arrived.
     */
    func selfTestArrived(nonce: String) 
    
    /**
     * The saved connections: `listed` the ones the store decoded, `all`
     * every one it holds (nil while that can't be told).
     */
    func setSaved(listed: [String], all: [String]?) 
    
    /**
     * The settings care reads, as they are now.
     */
    func setSettings(notifications: Bool, liveActivity: Bool, relayUrl: String, declined: [String], unpaired: [String]) 
    
    /**
     * What the page told the host (`{"ev": …}`): `agent` for `"agent"`.
     */
    func setupEvent(page: UInt64, ev: String, agent: String?) 
    
    /**
     * `{"op": "host-setup", …}` for screen `page`, in `locale`.
     */
    func setupMessage(page: UInt64, locale: String)  -> String?
    
    /**
     * A session's control plane for `connection` came up.
     */
    func tend(connection: CareConnection) 
    
}
