    public static func lower(_ value: SessionEventSink) -> UInt64 {
         if let rustImpl = value as? SessionEventSinkImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SessionEventSink {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SessionEventSink, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


