/**
 * Why a borrowed connection couldn't do what was asked.
 */
public enum BorrowFailure: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The session isn't connected now (or there's no such session).
     */
    case NotConnected
    /**
     * The connection or a channel on it failed (`log`: English, for the
     * log only).
     */
    case Ssh(cause: FailureCauseValue, log: String
    )
    /**
     * SFTP said no to `path`.
     */
    case Sftp(why: SftpWhyValue, path: String, log: String
    )
    /**
     * The progress callback asked to stop.
     */
    case Cancelled

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

