        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotConnected
        case 2: return .Ssh(
            cause: try FfiConverterTypeFailureCauseValue.read(from: &buf), 
            log: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Sftp(
            why: try FfiConverterTypeSftpWhyValue.read(from: &buf), 
            path: try FfiConverterString.read(from: &buf), 
            log: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BorrowFailure, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotConnected:
            writeInt(&buf, Int32(1))
        
        
        case let .Ssh(cause,log):
            writeInt(&buf, Int32(2))
            FfiConverterTypeFailureCauseValue.write(cause, into: &buf)
            FfiConverterString.write(log, into: &buf)
            
        
        case let .Sftp(why,path,log):
            writeInt(&buf, Int32(3))
            FfiConverterTypeSftpWhyValue.write(why, into: &buf)
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(log, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(4))
        
        }
    }
}


