    typealias SwiftType = ConnectionSaveRefusal

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnectionSaveRefusal {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NewSecretNeeded(
            auth: try FfiConverterTypeStoreAuthMethod.read(from: &buf)
            )
        case 2: return .Incomplete
        case 3: return .Invalid(
            why: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Gone

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ConnectionSaveRefusal, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .NewSecretNeeded(auth):
            writeInt(&buf, Int32(1))
