 * say in the person's language.
 */

public enum FailureCauseValue: Equatable, Hashable {
    
    case plain
    case unreachable(host: String, port: UInt16, why: UnreachableValue
    )
    case proxy(proxy: String, why: ProxyFailureValue
    )
    case handshake(host: String, port: UInt16, timedOut: Bool
    )
    case hostKey(host: String, port: UInt16, changed: Bool
    )
    case hostKeysLocked(host: String, port: UInt16
    )
    case credentials(why: CredentialsWhyValue
    )
    case channel(timedOut: Bool
    )
    case moshBootstrap(why: MoshWhyValue
    )





}

