extension FailureCauseValue: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFailureCauseValue: FfiConverterRustBuffer {
    typealias SwiftType = FailureCauseValue

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FailureCauseValue {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .plain
        
        case 2: return .unreachable(host: try FfiConverterString.read(from: &buf), port: try FfiConverterUInt16.read(from: &buf), why: try FfiConverterTypeUnreachableValue.read(from: &buf)
        )
        
        case 3: return .proxy(proxy: try FfiConverterString.read(from: &buf), why: try FfiConverterTypeProxyFailureValue.read(from: &buf)
        )
        
        case 4: return .handshake(host: try FfiConverterString.read(from: &buf), port: try FfiConverterUInt16.read(from: &buf), timedOut: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .hostKey(host: try FfiConverterString.read(from: &buf), port: try FfiConverterUInt16.read(from: &buf), changed: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .hostKeysLocked(host: try FfiConverterString.read(from: &buf), port: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 7: return .credentials(why: try FfiConverterTypeCredentialsWhyValue.read(from: &buf)
        )
        
        case 8: return .channel(timedOut: try FfiConverterBool.read(from: &buf)
        )
        
        case 9: return .moshBootstrap(why: try FfiConverterTypeMoshWhyValue.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FailureCauseValue, into buf: inout [UInt8]) {
        switch value {
        
        
        case .plain:
            writeInt(&buf, Int32(1))
        
        
        case let .unreachable(host,port,why):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(host, into: &buf)
            FfiConverterUInt16.write(port, into: &buf)
            FfiConverterTypeUnreachableValue.write(why, into: &buf)
            
        
        case let .proxy(proxy,why):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(proxy, into: &buf)
            FfiConverterTypeProxyFailureValue.write(why, into: &buf)
            
        
        case let .handshake(host,port,timedOut):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(host, into: &buf)
            FfiConverterUInt16.write(port, into: &buf)
            FfiConverterBool.write(timedOut, into: &buf)
            
        
        case let .hostKey(host,port,changed):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(host, into: &buf)
            FfiConverterUInt16.write(port, into: &buf)
            FfiConverterBool.write(changed, into: &buf)
            
        
        case let .hostKeysLocked(host,port):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(host, into: &buf)
            FfiConverterUInt16.write(port, into: &buf)
            
        
        case let .credentials(why):
            writeInt(&buf, Int32(7))
            FfiConverterTypeCredentialsWhyValue.write(why, into: &buf)
            
        
        case let .channel(timedOut):
            writeInt(&buf, Int32(8))
            FfiConverterBool.write(timedOut, into: &buf)
            
        
        case let .moshBootstrap(why):
            writeInt(&buf, Int32(9))
            FfiConverterTypeMoshWhyValue.write(why, into: &buf)
            
        }
    }
}


