/**
 * Why a key can't be imported or made — each one something the person can
 * act on; the host words it (iOS: `SSHKeyImportError`).
 */
public enum KeyImportFailure: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Not a private key the app reads.
     */
    case Unrecognized
    /**
     * A private key, but cut short or garbled.
     */
    case Damaged
    /**
     * Behind a passphrase, and none was given.
     */
    case NeedsPassphrase
    /**
     * The passphrase doesn't open it.
     */
    case WrongPassphrase
    /**
     * A FIDO security key: its private half is on the token.
     */
    case SecurityKey
    /**
     * A kind of key that can't sign in ("DSA", "Ed448", …).
     */
    case Unsupported(kind: String
    )
    /**
     * Encrypted with a scheme the app can't undo ("PKCS #12 PBE", …).
     */
    case UnsupportedEncryption(scheme: String
    )
    /**
     * Making or encoding the key failed.
     */
    case Failed(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension KeyImportFailure: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeKeyImportFailure: FfiConverterRustBuffer {
    typealias SwiftType = KeyImportFailure

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> KeyImportFailure {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Unrecognized
        case 2: return .Damaged
        case 3: return .NeedsPassphrase
        case 4: return .WrongPassphrase
        case 5: return .SecurityKey
        case 6: return .Unsupported(
            kind: try FfiConverterString.read(from: &buf)
            )
        case 7: return .UnsupportedEncryption(
            scheme: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Failed(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: KeyImportFailure, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Unrecognized:
            writeInt(&buf, Int32(1))
        
        
        case .Damaged:
            writeInt(&buf, Int32(2))
        
        
        case .NeedsPassphrase:
            writeInt(&buf, Int32(3))
        
        
        case .WrongPassphrase:
            writeInt(&buf, Int32(4))
        
        
        case .SecurityKey:
            writeInt(&buf, Int32(5))
        
        
        case let .Unsupported(kind):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(kind, into: &buf)
            
        
        case let .UnsupportedEncryption(scheme):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(scheme, into: &buf)
            
        
        case let .Failed(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


