public enum SessionEventKind: Equatable, Hashable {
    
    case state(state: SessionStateValue
    )
    /**
     * The panes with terminals for attach number `attach`; keep showing
     * the previous attach's views until [`SessionEventKind::FirstFrame`]
     * for this one.
     */
    case panes(attach: UInt64, panes: [PaneValue]
    )
    case firstFrame(attach: UInt64
    )
    /**
     * tmux's tree, or what the chrome draws around it, changed:
     * [`CoreSessions::tmux_view`].
     */
    case treeChanged
    case paneActivity(pane: String
    )
    case paneBell(pane: String
    )
    case agentHooksUpdated
    case attachStalled
    case tmuxActionsDropped
    case hostKeyPrompt(prompt: UInt64, host: String, port: UInt16, fingerprint: String, 
        /**
         * The trusted fingerprint, when the key CHANGED.
         */previous: String?, 
        /**
         * `ssh-rsa` when the server offers no better host-key algorithm
         * (B564).
         */olderAlgorithm: String?
    )
    /**
     * The connection had to use an older host-key algorithm (B564).
     */
    case olderHostKeyAlgorithm(algorithm: String
    )
    case hostKeyPromptWithdrawn(prompt: UInt64
    )
    /**
     * What the server asks at sign-in that the saved password doesn't
     * answer (a one-time code, B563), in its own words; answer with
     * `answer_question`.
     */
    case signInQuestion(prompt: UInt64, host: String, name: String, instructions: String, text: String, 
        /**
         * Whether the answer is shown as typed (false: a secret).
         */echo: Bool
    )
    case signInQuestionWithdrawn(prompt: UInt64
    )
    case degraded(degrade: DegradeValue
    )
    case returnPathDead
    case returnPathAlive
    case moshMetrics(srttMs: Double, roaming: Bool
    )
    /**
     * mosh's protocol counters (the transport pill's long-press popover),
     * at most twice a second while they move.
     */
    case moshDiagnostics(datagramsReceived: UInt64, parseFailures: UInt64, gapEvents: UInt64, appliedHostNum: UInt64, packetsSent: UInt64, lastUserNum: UInt64, serverAckedUserNum: UInt64, 
        /**
         * The UDP flow's state: `setup`, `preparing`, `waiting`, `ready`,
         * `failed` or `cancelled`.
         */channelState: String, inputHeld: Bool
    )
    case inputDiscarded(stream: UInt64, bytes: UInt64, why: DiscardedValue
    )
    /**
     * The way back from the background asked the connection that was live
     * when the app left, and heard (resume in place): what the device's
     * diagnostics log.
     */
    case resumeChecked(awayMs: UInt64, 
        /**
         * 0 when there was nothing to ask (the connection was gone before
         * the return).
         */waitedMs: UInt64, outcome: ResumeOutcomeValue, 
        /**
         * Asked on tmux's control channel (else the SSH keepalive, or
         * nothing).
         */throughTmux: Bool, 
        /**
         * Writes typed meanwhile: sent when kept, dropped otherwise.
         */held: UInt32
    )
    /**
     * [`CoreSessions::disconnect`] has torn the session down.
     */
    case closed
    /**
     * [`CoreSessions::flush`]'s answer.
     */
    case flushed(token: UInt64
    )
    /**
     * What a herdr request ([`CoreSessions::herdr`]) came back with.
     */
    case herdrAnswer(token: UInt64, answer: HerdrAnswerValue
    )
    /**
     * [`CoreSessions::deliver`]'s answer: whether the content went out.
     */
    case delivered(token: UInt64, delivered: Bool
    )





}

